local KCookie = CS.Engine.Lib.KCookie
local UIModule = CS.Engine.UI.UIModule
local TimeZoneUtils = CS.Engine.Http.TimeZoneUtils
---@type ActivityConstants
local ActivityConstants = import("Game.Activity.ActivityConstants")

---@class ActivityUtils
local ActivityUtils = Class('ActivityUtils')


---转换活动列表剩余时间文本
---@param timestamp integer @ 活动结束时间戳
---@return string
function ActivityUtils.ConventLeftTimeText(timestamp)
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if not comp then return end
    local curTime = comp:GetPlayerDojo():GetServerTime()
    curTime = curTime or os.time()
    local seconds = checkInt(timestamp) - curTime
    if seconds <= 0 then
        return localize("活动已结束")
    end
    return CfUtils.GetTimeHMS10(seconds)
end


---时间是否紧急(剩余时间不足3天)
---@param timestamp integer @ 活动结束时间戳
---@return boolean
function ActivityUtils.IsUrgentTime(timestamp)
    local seconds = checkInt(timestamp) - os.time()
    return seconds <= 86400 * 3
end


---通过活动类型获取活动图标路径
---@param activityType integer @ 活动类型
---@return string
function ActivityUtils.GetActivityIconPathByActivityType(activityType)
    local config = ActivityConstants.Configs[checkInt(activityType)]
    if config and config.iconPath then
        return config.iconPath
    else
        ---@type ActivityEnumVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting2500, "ActivityEnumVo", checkString(activityType)) or {}
        return vo.icon
    end
end


---刷新活动页面导航栏
---@param itemId string[] @ 道具id列表
function ActivityUtils.RefreshNavigatorGoods(itemId)
    local goodsList = checkTable(itemId) -- string.split(checkString(itemId), ";")
    CfUtils.RefreshTopGoods(goodsList)
end


---更新活动主页红点状态
---@param activityId integer @ 活动id
---@param state      integer @ 红点状态(-1:关闭 0:开启)
function ActivityUtils.UpdateActivityMainRedPointState(activityId, state)
    Events.Broadcast(Constants.EventNames.ActivityRedPointChange, activityId, state)
end


---获取图片完整路径
---@param path string 配表中的缩略路径，因为活动中会出现图片路径通过接口返回的情况，所以这里做一次路径补全
---@param isLang string 是否添加语言索引
---@return string
function ActivityUtils.GetImageFullPath(path ,isLang)
    if path == nil then return end
    local strs = string.split(path, ":")
    if #strs == 1 then
        return path
    end
    local str2 = strs[2]
    if isLang then
        local langSuffix = GameUtils.GetLangSuffix()
        if not string.isEmpty(langSuffix) then
            str2 = str2 .. langSuffix
        end
    end
    return CS.GameUtils.GetCombineResourceDirPath(checkInt(strs[1]), str2)
end


---将活动时间中的剩余秒数转换为时间戳
---@param activityData table @ 活动数据
function ActivityUtils.ConventSecondToTimeStamp(activityData)
    GameUtils.ConventSecondToTimeStamp(activityData)
end


---获取活动持续时间
---@param startTime integer @ 开始时间
---@param endTime   integer @ 结束时间
---@return string
function ActivityUtils.ConventActivityDurationTime(startTime, endTime)
    return GameUtils.CheckUTCTimeformat(GameUtils.l10nTimeData("%m/%d", startTime).."-"..GameUtils.l10nTimeData("%m/%d  %H:%M", endTime))
end


---获取活动dojo持续时间
---@param activityDojo ActivityDojo
---@return string
function ActivityUtils.ConventActivityDojoDurationTime(activityDojo)
    return ActivityUtils.ConventActivityDurationTime(activityDojo.startTime, activityDojo.endTime)
end

---获取活动结束时间
---@param closeTime   integer @ 结束时间
function ActivityUtils.ConvertActivityCloseTime(closeTime)
    -- 显示距离关闭的剩余天数 / 距离开启的剩余天数
    ---@type PlayerComponent
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
    local leftTime = closeTime - curDate
    if leftTime < 0 then
        return localize("已结束")
    end

    return CfUtils.GetTimeHMS7(leftTime)
end

---打开活动主页面
---@param activityId  integer @ 要打开的活动页签
---@param excludeIds  table   @ 是否关闭互斥的窗口
---@param exParameter table   @ 额外参数
---@param isStack     boolean @ 是否加入堆栈
function ActivityUtils.OpenActivityView(activityId, excludeIds, exParameter, isStack)
    isStack = isStack ~= false and true or false ---初始为true入栈的操作
    if activityId then
        KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, checkInt(activityId))
    end
    KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_TYPE, Constants.MainActivityType.NORMAL)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActivityMainDialog, parameters = {exParameter = exParameter} }, excludeIds, isStack)
end

---活动是否开启
---@param activityDojo ActivityDojo
---@return boolean
function ActivityUtils.IsActivityStart(activityDojo)
    return os.time() >= checkInt(activityDojo.startTime)
end

---活动是否可进入
---@param activityDojo ActivityDojo
---@return boolean
function ActivityUtils.IsActivityEnabled(activityDojo)
    return os.time() <= checkInt(activityDojo.endTime)
end


---活动是否关闭
---@param activityDojo ActivityDojo
---@return boolean
function ActivityUtils.IsActivityClosed(activityDojo)
    return os.time() <= checkInt(activityDojo.closeTime)
end

---记录活动进入时间
---@param activityUuid integer @ 活动id
---@return integer
function ActivityUtils.WriteActivityEnterTime(activityUuid)
    local enterTimeKey   = string.format('Activity_Enter_Time_%s_%s', tostring(activityUuid), GameUtils.GetPlayerId())
    local enterTimeValue = TimeZoneUtils.UtcSeconds
    CfUtils.WriteLocalData(enterTimeKey, tostring(enterTimeValue))
    return enterTimeValue
end


---获取活动进入时间
---@param activityUuid integer @ 活动id
---@return integer
function ActivityUtils.GetActivityEnterTime(activityUuid)
    local enterTimeKey = string.format('Activity_Enter_Time_%s_%s', tostring(activityUuid), GameUtils.GetPlayerId())
    return checkInt(CfUtils.GetLocalData(enterTimeKey, "0"))
end

--- 判断是否是活动集合
---@param activityData any
function ActivityUtils.IsCollectionActivity(activityData)
    return isNotNull(activityData.isCollection) and checkNumber(activityData.isCollection) == 1
end

--- 从活动集合中获取子活动
---@param collectionDojo any
---@param subId any
function ActivityUtils.GetSubActivityDojo(collectionDojo, subId)
    subId = checkNumber(subId)
    local datas = collectionDojo.collectionDatas
    for i, v in ipairs(datas) do
        if v.id == subId then
            return v
        end
    end
    return datas[1]
end

--- 获取子活动id
function ActivityUtils.GetSubActivityId()
    local subId = KCookie.Get(Constants.UICacheDataKeys.UI_ACTIVITY_SUB_SELECTED_ACTIVITY_ID)
    return subId
end

